async (page) => {
 const checks=[],contractOutputs=[];
 const render=async id=>{await page.setViewportSize({width:1440,height:900});await page.evaluate(id=>window.DW_PROTOTYPE.renderScreen(id),id);await page.waitForFunction(id=>window.DW_READY===id,id);};
 const route=async id=>page.waitForFunction(id=>window.DW_READY===id,id);
 const click=async name=>page.locator('[data-rec-action="'+name+'"]').click();
 const verify=async(name,fn)=>{if(!await page.evaluate(fn))throw Error(name);checks.push({name,result:'pass'});};
 const collect=async(name,schema,fn,type,context)=>{const value=await page.evaluate(fn);const row={name,schema,value};if(type)row.recordingType=type;if(context)row.context=await page.evaluate(context);contractOutputs.push(row);};
 const replayContext=()=>{const r=window.DW_DESIGN_STATE.recording;return {trajectory:window.DW_RECORDING.currentTrajectory(),topology:r.topology,allowedDisplayIds:r.topology.displays.map(d=>d.displayId),targetKind:'desktop'};};
 await render('record-config');
 await verify('录制准备默认覆盖全部活动显示屏',()=>{const r=window.DW_DESIGN_STATE.recording;return r.scope==='allDisplays'&&r.topology.displays.length===3&&document.querySelector('[data-rec-scope]:checked').value==='allDisplays';});
 const proportions=await page.locator('.rec-monitor').evaluateAll(nodes=>nodes.map((e,i)=>{const rect=e.getBoundingClientRect(),display=window.DW_DESIGN_STATE.recording.topology.displays[i];return Math.abs(rect.width/rect.height-display.bounds.width/display.bounds.height)<.02;}));
 if(!proportions.every(Boolean))throw Error('显示屏预览未保持物理比例');checks.push({name:'显示屏布局保持横竖屏物理比例',result:'pass'});
 await click('start');await route('record-active');
 await verify('全部显示屏启动固定同一来源和时间轴',()=>{const r=window.DW_DESIGN_STATE.recording;return r.source.scope==='allDisplays'&&r.source.displayIds.length===3&&r.state==='recording'&&r.lastStartRequest.expectedTopologyVersion===r.source.topology.version;});
 await collect('录制显示拓扑','recording.schema.json#/$defs/topology',()=>window.DW_DESIGN_STATE.recording.topology,'topology');
 await collect('全部显示屏录制来源','recording.schema.json#/$defs/source',()=>window.DW_DESIGN_STATE.recording.source,'source');
 await collect('全部显示屏启动参数','service.schema.json#/$defs/record.start/properties/params',()=>window.DW_DESIGN_STATE.recording.lastStartRequest,'start',()=>{const r=window.DW_DESIGN_STATE.recording;return {targetToken:r.lastStartRequest.targetToken,targetKind:'desktop',topology:r.topology,permissions:['record']};});
 await collect('全部显示屏启动结果','service.schema.json#/$defs/record.start/properties/result',()=>window.DW_DESIGN_STATE.recording.startResult,'startResult');
 await collect('录制中快照','service.schema.json#/$defs/record.snapshot/properties/result',()=>window.DW_RECORDING.snapshot(),'snapshot');
 await click('pause');await route('record-paused');
 await verify('跨屏暂停保持原显示集合',()=>{const r=window.DW_DESIGN_STATE.recording;return r.state==='paused'&&r.reason==='USER_PAUSED'&&r.source.displayIds.length===3;});
 await click('resume');await route('record-active');await click('finish');await route('trajectory-editor');
 await verify('跨屏拖拽与来源随轨迹一起保存',()=>{const r=window.DW_DESIGN_STATE.recording,t=r.output;return t.source.displayIds.length===3&&t.events.some(e=>e.kind==='pointer.move'&&e.x<0)&&t.events.some(e=>e.kind==='pointer.move'&&e.y<0)&&t.events.filter(e=>e.kind==='pointer.button').map(e=>e.state).join(',')==='down,up';});
 await collect('跨屏轨迹编辑结果','trajectory.schema.json',()=>window.DW_DESIGN_STATE.recording.output);
 await render('record-config');await page.locator('[data-rec-scope][value="display"]').check();await page.locator('[data-rec-field="display"]').selectOption('portrait-left');await click('start');await route('record-active');
 await verify('单屏选择只录指定竖屏',()=>{const s=window.DW_DESIGN_STATE.recording.source;return s.scope==='display'&&s.displayIds.join(',')==='portrait-left'&&s.initialPointer.x<0;});
 await verify('单屏时长和浮条使用当前事件',()=>{const snapshot=window.DW_RECORDING.snapshot();return snapshot.durationUs===500000&&snapshot.eventCount===4&&document.querySelector('.record-clock').textContent==='00:00.50';});
 await click('finish');await route('trajectory-editor');await collect('单屏轨迹','trajectory.schema.json',()=>window.DW_DESIGN_STATE.recording.output);
 await verify('单屏时间轴只绘制实际输入轨道',()=>{const lanes=[...document.querySelectorAll('.track')];return lanes.find(e=>e.querySelector(':scope>span').textContent==='键盘').querySelectorAll('.timeline-bar').length===0&&lanes.find(e=>e.querySelector(':scope>span').textContent==='鼠标按钮').querySelectorAll('.timeline-bar').length===1;});
 await page.getByRole('button',{name:'显示屏映射',exact:true}).click();await route('trajectory-displays');
 await verify('单屏映射仅列出本次录制来源',()=>document.querySelectorAll('[data-rec-map]').length===1&&document.querySelector('[data-rec-map]').dataset.recMap==='portrait-left');
 await page.locator('[data-rec-field="mappingMode"]').selectOption({label:'按屏内像素平移'});await click('apply-mapping');
 await collect('单屏回放映射','recording.schema.json#/$defs/displayMapping',()=>window.DW_DESIGN_STATE.recording.mappingOutput,'replay',replayContext);
 await page.getByRole('button',{name:'返回时间轴',exact:true}).click();await route('trajectory-editor');
 await page.getByRole('button',{name:'精确裁剪',exact:true}).click();await route('trajectory-trim');
 await verify('录制后裁剪读取同一竖屏轨迹',()=>{const t=window.DW_DESIGN_STATE.completion.trim,r=window.DW_DESIGN_STATE.recording;return JSON.stringify(t.source)===JSON.stringify(r.output)&&t.source.source.displayIds.join(',')==='portrait-left';});
 await page.locator('[data-cp-action="trim-preview"]').click();await page.locator('[data-cp-action="trim-apply"]').click();
 await collect('单屏录制后的完整裁剪','trajectory.schema.json',()=>window.DW_DESIGN_STATE.completion.trim.output);
 await verify('裁剪结果进入当前轨迹且保留末尾释放',()=>{const t=window.DW_RECORDING.currentTrajectory();return t.events.length===4&&t.events.at(-1).state==='up'&&t.source.displayIds.join(',')==='portrait-left';});
 await page.locator('[data-cp-action="trim-undo"]').click();
 await verify('撤销裁剪恢复同次录制结果',()=>window.DW_RECORDING.currentTrajectory()===window.DW_DESIGN_STATE.recording.output);
 await render('record-config');await page.locator('[data-rec-scope][value="window"]').check();await click('start');await route('record-active');
 await verify('窗口录制保留独立范围',()=>window.DW_DESIGN_STATE.recording.source.scope==='window');
 await render('record-config');await page.locator('[data-rec-field="coordinateMode"]').selectOption({label:'原始相对移动'});await click('start');await route('record-active');
 await collect('相对录制快照','service.schema.json#/$defs/record.snapshot/properties/result',()=>window.DW_RECORDING.snapshot(),'snapshot');
 await click('finish');await route('trajectory-editor');await page.getByRole('button',{name:'显示屏映射',exact:true}).click();await route('trajectory-displays');await click('apply-mapping');
 await collect('相对轨迹原布局回放','recording.schema.json#/$defs/displayMapping',()=>window.DW_DESIGN_STATE.recording.mappingOutput,'replay',replayContext);
 await page.locator('[data-rec-field="mappingMode"]').selectOption({label:'按屏内像素平移'});
 if(await page.locator('[data-rec-action="apply-mapping"]').isEnabled())throw Error('相对轨迹仍可按屏内像素平移');checks.push({name:'相对录制回放拒绝物理像素映射',result:'pass'});
 await render('record-active');await page.evaluate(()=>{const next=structuredClone(window.DW_DESIGN_STATE.recording.topology);next.version++;next.displays=next.displays.filter(d=>d.displayId!=='top');next.virtualBounds={x:-1440,y:0,width:4000,height:2560};window.DW_DESIGN_STATE.applyRecordingTopology(next);});await route('record-topology-changed');
 await verify('布局变化结束原分段并固定旧来源',()=>{const r=window.DW_DESIGN_STATE.recording;return r.state==='interrupted'&&r.partial&&r.source.topology.version===42&&r.source.displayIds.length===3&&r.topology.version===43&&r.topology.displays.length===2;});
 if(await page.locator('[data-rec-action="resume"]').count())throw Error('布局变化仍提供继续原录制');checks.push({name:'布局变化不允许继续旧录制',result:'pass'});
 await collect('布局变化快照','service.schema.json#/$defs/record.snapshot/properties/result',()=>window.DW_RECORDING.snapshot(),'snapshot');
 await click('finish');await route('trajectory-editor');await collect('中断分段仍带原布局','trajectory.schema.json',()=>window.DW_DESIGN_STATE.recording.output);
 await render('record-topology-changed');await click('restart');await route('record-config');await click('start');await route('record-active');
 await verify('按当前屏幕新建录制使用新拓扑',()=>{const r=window.DW_DESIGN_STATE.recording;return r.source.displayIds.length===2&&r.source.topology.version===43&&r.lastStartRequest.expectedTopologyVersion===43;});
 await click('finish');await route('trajectory-editor');await collect('新布局录制结果','trajectory.schema.json',()=>window.DW_DESIGN_STATE.recording.output);
 await render('record-unavailable');if(await page.locator('[data-rec-action="start"]').count())throw Error('无显示屏仍可开始录制');await click('refresh');await route('record-config');await verify('显示屏恢复后可重新选择范围',()=>window.DW_DESIGN_STATE.recording.topology.displays.length===3);
 await render('trajectory-displays');await click('apply-mapping');
 await collect('原布局回放映射','recording.schema.json#/$defs/displayMapping',()=>window.DW_DESIGN_STATE.recording.mappingOutput,'replay',replayContext);
 await page.locator('[data-rec-field="mappingMode"]').selectOption({label:'按屏内像素平移'});await click('apply-mapping');
 await collect('逐屏物理偏移映射','recording.schema.json#/$defs/displayMapping',()=>window.DW_DESIGN_STATE.recording.mappingOutput,'replay',replayContext);
 await page.locator('[data-rec-map="portrait-left"]').selectOption('main');if(await page.locator('[data-rec-action="apply-mapping"]').isEnabled())throw Error('重复目标仍可应用映射');checks.push({name:'回放映射拒绝重复目标',result:'pass'});
 await page.locator('[data-rec-map="portrait-left"]').selectOption('portrait-left');if(!await page.locator('[data-rec-action="apply-mapping"]').isEnabled())throw Error('有效映射无法应用');checks.push({name:'修正映射后恢复应用操作',result:'pass'});
 await render('trajectory-displays-invalid');if(await page.locator('[data-rec-action="apply-mapping"]').isEnabled())throw Error('缺失屏幕仍可应用映射');await verify('缺失显示屏保持未匹配状态',()=>window.DW_DESIGN_STATE.recording.mapping.top==='');
 await render('trajectory-trim');await page.evaluate(()=>{const t=window.DW_DESIGN_STATE.completion.trim;t.source=structuredClone(window.DW_CATALOG.recordingFixtures.trajectory);t.sourceVersion++;t.durationUs=1000000;t.fromUs=0;t.untilUs=1000000;t.preview=null;});
 await page.locator('[data-cp-field="trim-from"]').fill('0');await page.locator('[data-cp-field="trim-until"]').fill('1000');await page.locator('[data-cp-action="trim-preview"]').click();await page.locator('[data-cp-action="trim-apply"]').click();
 await verify('裁剪完整轨迹保持显示来源',()=>{const t=window.DW_DESIGN_STATE.completion.trim.output;return t.source.scope==='allDisplays'&&t.source.displayIds.length===3&&t.source.initialPointer.x===800;});
 await page.locator('[data-cp-field="trim-from"]').fill('600');await page.locator('[data-cp-action="trim-preview"]').click();await page.locator('[data-cp-action="trim-apply"]').click();
 await verify('裁剪起点采用此前实际指针位置',()=>{const t=window.DW_DESIGN_STATE.completion.trim.output;return t.source.initialPointer.x===-400&&t.source.initialPointer.y===700&&t.events[0].atUs===100000;});
 await collect('跨屏轨迹裁剪输出','trajectory.schema.json',()=>window.DW_DESIGN_STATE.completion.trim.output);
 return {checks,contractOutputs};
}
